  -webkit-appearance: none !important;
  margin: 0 !important;
}
.stNumberInput input[type="number"] { -moz-appearance: textfield !important; }

/* ─── Animated Gradient Border for Scorecards ────────────────────────────────*/
@keyframes gradient-border {
  0% { border-color: rgba(0, 255, 135, 0.5); box-shadow: 0 0 12px rgba(0, 255, 135, 0.2); }
  50% { border-color: rgba(0, 210, 255, 0.5); box-shadow: 0 0 20px rgba(0, 210, 255, 0.25); }
  100% { border-color: rgba(0, 255, 135, 0.5); box-shadow: 0 0 12px rgba(0, 255, 135, 0.2); }
}
.scorecard-animated {
  animation: gradient-border 3s ease-in-out infinite;
}

/* ─── Utility Card Classes ────────────────────────────────────────────────────*/
.card-positive {
  border-color: rgba(0, 255, 135, 0.35) !important;
  box-shadow: 0 0 12px rgba(0, 255, 135, 0.08), var(--shadow-dark) !important;
}
.card-negative {
  border-color: rgba(255, 61, 90, 0.35) !important;
  box-shadow: 0 0 12px rgba(255, 61, 90, 0.08), var(--shadow-dark) !important;
}
.card-neutral {
  border-color: rgba(255, 214, 0, 0.3) !important;
  box-shadow: 0 0 12px rgba(255, 214, 0, 0.06), var(--shadow-dark) !important;
}

/* ─── Sidebar Footer / Branding ──────────────────────────────────────────────*/
.sidebar-footer {
  position: fixed;
  bottom: 0;
  left: 0;
  width: inherit;
  padding: 0.75rem 1rem;
  background: var(--panel-bg);
  border-top: 1px solid var(--border-color);
  font-size: 0.7rem;
  color: #475569;
  font-family: var(--font-mono);
  letter-spacing: 0.04em;
  z-index: 1000;
}

/* ─── Selectbox Open Dropdown Styling ────────────────────────────────────────*/
[data-baseweb="popover"] [data-baseweb="menu"] {
  background: #0e1524 !important;
  border: 1px solid var(--border-color) !important;
  border-radius: var(--border-radius-md) !important;
  box-shadow: 0 20px 40px rgba(0,0,0,0.6) !important;
}
[data-baseweb="popover"] [role="option"] {
  color: var(--text-muted) !important;
  font-family: var(--font-mono) !important;
  font-size: 0.82rem !important;
  padding: 0.5rem 1rem !important;
  transition: background 0.15s ease !important;
}
[data-baseweb="popover"] [role="option"]:hover,
[data-baseweb="popover"] [role="option"][aria-selected="true"] {
  background: rgba(0, 255, 135, 0.07) !important;
  color: var(--primary-color) !important;
}

/* ─── Form Submit Button (primary) ───────────────────────────────────────────*/
[data-testid="stFormSubmitButton"] > button {
  background: linear-gradient(135deg, rgba(0,255,135,0.15) 0%, rgba(0,210,255,0.08) 100%) !important;
  border-color: var(--primary-color) !important;
  color: var(--primary-color) !important;
  font-size: 0.95rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.04em !important;
  padding: 0.75rem 2rem !important;
  box-shadow: 0 0 16px rgba(0,255,135,0.2) !important;
}
[data-testid="stFormSubmitButton"] > button:hover {
  box-shadow: 0 0 28px rgba(0,255,135,0.4) !important;
  transform: translateY(-2px) !important;
}


/* ─── Progress Bar ────────────────────────────────────────────────────────────*/
[data-testid="stProgress"] > div > div {
  background: linear-gradient(90deg, var(--primary-color), var(--secondary-color)) !important;
  border-radius: 4px !important;
}
[data-testid="stProgress"] > div {
  background: rgba(30, 41, 59, 0.5) !important;
  border-radius: 4px !important;
}

/* ─── UI refinement pass ────────────────────────────────────────────────────
   Keep the B3Lab dark identity while improving hierarchy, rhythm and focus. */
:root {
  --content-max-width: 1440px;
  --surface-glass: rgba(14, 21, 36, 0.72);
  --surface-hover: rgba(19, 29, 46, 0.94);
  --focus-ring: 0 0 0 3px rgba(0, 210, 255, 0.22);
}

/* Give the content a calmer reading width and a more deliberate top rhythm. */
.main .block-container {
  max-width: var(--content-max-width) !important;
  padding-top: 3rem !important;
  padding-bottom: 4rem !important;
}

/* Reduce the visual noise of Streamlit's default vertical gaps. */
[data-testid="stVerticalBlock"] > [data-testid="stVerticalBlock"] {
  gap: 0.85rem;
}

/* Consistent interactive affordances. */
button,
[data-baseweb="select"],
[data-testid="stExpander"] summary,
[data-testid="stTabs"] [data-baseweb="tab"] {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
input:focus-visible,
textarea:focus-visible,
[data-baseweb="select"]:focus-within,
[data-testid="stExpander"] summary:focus-visible {
  outline: none !important;
  box-shadow: var(--focus-ring) !important;
}

/* Buttons: less glow, stronger contrast, clearer hierarchy. */
[data-testid="stButton"] > button {
  min-height: 2.5rem;
  border-radius: 9px !important;
  border-color: #2a3a50 !important;
  background: rgba(19, 29, 46, 0.82) !important;
  color: var(--text-main) !important;
  font-family: var(--font-display) !important;
  font-weight: 600 !important;
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, box-shadow 160ms ease !important;
}
[data-testid="stButton"] > button:hover {
  transform: translateY(-1px) !important;
  border-color: rgba(0, 210, 255, 0.65) !important;
  background: var(--surface-hover) !important;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.22) !important;
}
[data-testid="baseButton-primary"] {
  background: linear-gradient(110deg, rgba(0, 255, 135, 0.2), rgba(0, 210, 255, 0.14)) !important;
}

/* Make the hero feel like a product header instead of a large empty banner. */
.page-hero {
  min-height: 122px;
  background:
    radial-gradient(circle at 90% 15%, rgba(0, 210, 255, 0.12), transparent 34%),
    linear-gradient(135deg, rgba(14, 27, 47, 0.98), rgba(8, 12, 20, 0.96)) !important;
  border-color: rgba(71, 91, 118, 0.7) !important;
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.035) !important;
}
.page-hero-title { font-size: clamp(1.5rem, 2.3vw, 2rem) !important; }
.page-hero-subtitle { max-width: 760px; font-size: 0.95rem; }

/* Tables read as data products, not raw Streamlit output. */
[data-testid="stDataFrame"] {
  border: 1px solid var(--panel-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.18);
}

/* Keep content comfortable on narrow screens. */
@media (max-width: 768px) {
  .main .block-container {
    padding-top: 4rem !important;
    padding-bottom: 2.5rem !important;
  }
  .page-hero { min-height: 0; }
  [data-testid="stButton"] > button { min-height: 2.75rem; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

/* ─── Selector polish ────────────────────────────────────────────────────────*/
.stMultiSelect [data-baseweb="select"] input::placeholder,
.stSelectbox [data-baseweb="select"] input::placeholder {
  color: #94a3b8 !important;
  opacity: 1 !important;
}
.stMultiSelect [data-baseweb="select"] input,
.stSelectbox [data-baseweb="select"] input {
  caret-color: var(--brand-secondary) !important;
}
[data-testid="stTooltipHoverTarget"] {
  color: var(--brand-secondary) !important;
}

[data-testid="stTooltipHoverTarget"] > div {
  color: #475569 !important;
  transition: color 0.2s ease !important;
}
[data-testid="stTooltipHoverTarget"] > div:hover { color: var(--secondary-color) !important; }
[data-testid="stTooltipContent"] {
  background: #0f1a2e !important;
  border: 1px solid rgba(0, 210, 255, 0.25) !important;
  border-radius: var(--border-radius-md) !important;
  color: var(--text-main) !important;
  font-family: var(--font-display) !important;
  font-size: 0.78rem !important;
  box-shadow: 0 8px 24px rgba(0,0,0,0.5) !important;
  max-width: 280px !important;
  padding: 0.6rem 0.9rem !important;
  line-height: 1.5 !important;
}

/* ─── Plotly Chart Border Radius ─────────────────────────────────────────────*/
.js-plotly-plot .plotly {
  border-radius: var(--border-radius-md) !important;
  overflow: hidden !important;
}

/* ─── Checkbox Styling ───────────────────────────────────────────────────────*/
[data-testid="stCheckbox"] label {
  font-family: var(--font-display) !important;
  font-size: 0.85rem !important;
  color: var(--text-muted) !important;
  transition: color 0.2s ease !important;
}
[data-testid="stCheckbox"] label:hover { color: var(--text-main) !important; }
[data-testid="stCheckbox"] [data-baseweb="checkbox"] [data-checked="true"] div {
  background: var(--primary-color) !important;
  border-color: var(--primary-color) !important;
}

/* ─── Multiselect Dropdown Improvements ──────────────────────────────────────*/
[data-baseweb="tag"] span { font-size: 0.75rem !important; }
[data-baseweb="tag"] [role="button"] { opacity: 0.7 !important; }
[data-baseweb="tag"] [role="button"]:hover { opacity: 1 !important; }

/* ─── Hero hover animation ───────────────────────────────────────────────────*/
.page-hero {
  transition: box-shadow 0.3s ease, border-color 0.3s ease !important;
}
.page-hero:hover {
  border-left-color: var(--secondary-color) !important;
  box-shadow: var(--shadow-dark), 0 0 30px rgba(0, 210, 255, 0.08) !important;
}
.main-hero:hover { border-left-color: var(--primary-color) !important; }

/* ─── Hide Streamlit Native Loading Indicators ───────────────────────────────*/
/* Top progress decoration bar */
[data-testid="stDecoration"] { display: none !important; }
/* Top-right running/status widget */
[data-testid="stStatusWidget"] { display: none !important; }
/* Native spinner text (we use glassmorphic spinners instead) */
[data-testid="stSpinner"] > div > p { display: none !important; }
/* Hide Streamlit top toolbar when in embedded/app mode */
[data-testid="stToolbar"] { display: none !important; }
/* Hide "Made with Streamlit" footer */
footer { display: none !important; }
footer::after { display: none !important; }
#MainMenu { display: none !important; }

/* ─── UI polish pass — clearer hierarchy for the analysis workspace ───────── */
.ui-section-heading {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  margin: 1.65rem 0 0.75rem !important;
  padding: 0 0 0.65rem !important;
  border-bottom: 1px solid rgba(71, 91, 118, 0.5);
  font-size: clamp(1rem, 1.45vw, 1.2rem) !important;
  letter-spacing: -0.015em !important;
}

.analyst-synthesis-heading {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 0.5rem !important;
}

.analyst-synthesis-heading svg {
  flex-shrink: 0;
}

.analyst-synthesis-title {
  color: var(--text-main) !important;
}

.analyst-synthesis-guide {
  margin: -0.15rem 0 0.8rem !important;
  padding-left: 0.6rem;
  border-left: 2px solid var(--brand-primary);
  color: var(--text-muted);
  font-size: 0.76rem;
}

.analyst-synthesis-card {
  margin: 0 0 0.8rem;
  padding: 1rem 1.1rem;
  border: 1px solid color-mix(in srgb, var(--panel-border) 78%, var(--brand-primary));
  border-radius: var(--radius-lg);
  background:
    radial-gradient(circle at 100% 0, rgba(97, 212, 198, 0.08), transparent 36%),
    linear-gradient(145deg, var(--panel-bg), #101722);
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.16);
}

.analyst-synthesis-card-header,
.analyst-synthesis-identity {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.6rem;
}

.analyst-synthesis-identity {
  justify-content: flex-start;
  flex-wrap: wrap;
}

.analyst-synthesis-identity strong {
  color: var(--brand-secondary);
  font-family: var(--font-mono);
  font-size: 0.95rem;
}

.analyst-synthesis-identity span {
  color: var(--text-main);
  font-size: 0.86rem;
  font-weight: 600;
}

.analyst-synthesis-sector {
  margin-top: 0.15rem;
  color: var(--text-faint);
  font-size: 0.7rem;
}

.analyst-category.is-positive { --analyst-signal: var(--brand-primary); }
.analyst-category.is-neutral { --analyst-signal: var(--brand-accent); }
.analyst-category.is-negative { --analyst-signal: var(--brand-danger); }

.analyst-synthesis-summary {
  display: flex;
  align-items: baseline;
  gap: 0.55rem;
  margin: 0.75rem 0 0.35rem !important;
  color: var(--text-muted);
  font-size: 0.8rem;
}

.analyst-synthesis-summary strong {
  color: var(--text-main);
  font-family: var(--font-mono);
  font-size: 1.05rem;
}

.analyst-synthesis-insufficient {
  color: var(--text-muted);
}

.analyst-category-grid {
  margin: 0 !important;
}

.analyst-category {
  min-height: 105px;
  justify-content: flex-start;
  gap: 0.35rem;
  padding: 0.75rem 0.65rem;
}

.analyst-category-status {
  color: var(--analyst-signal) !important;
  font-family: var(--font-display) !important;
  font-size: 0.85rem !important;
}

.analyst-synthesis-meter {
  width: min(100%, 120px);
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(174, 186, 202, 0.14);
}

.analyst-synthesis-meter span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--analyst-signal);
}

.analyst-synthesis-percentile {
  color: var(--text-faint);
  font-size: 0.66rem;
}

.analyst-synthesis-empty {
  margin: 0.4rem 0 !important;
  color: var(--text-muted);
  font-size: 0.78rem;
}

.analyst-synthesis-details {
  margin-top: 0.65rem;
  padding-top: 0.55rem;
  border-top: 1px solid rgba(71, 91, 118, 0.5);
}

.analyst-synthesis-details summary {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--brand-secondary);
  font-size: 0.74rem;
  font-weight: 600;
  cursor: pointer;
  list-style: none;
}

.analyst-synthesis-details summary::-webkit-details-marker { display: none; }
.analyst-synthesis-details summary::after {
  margin-left: auto;
  content: "+";
  color: var(--text-faint);
  font-size: 1rem;
}
.analyst-synthesis-details[open] summary::after { content: "−"; }
.analyst-synthesis-details summary span {
  color: var(--text-faint);
  font-size: 0.66rem;
}

.analyst-synthesis-detail-body > p {
  margin: 0.55rem 0 0.35rem !important;
  color: var(--text-faint);
  font-size: 0.66rem;
}

.analyst-synthesis-detail-group {
  margin-top: 0.45rem;
}

.analyst-synthesis-detail-group strong {
  color: var(--text-muted);
  font-size: 0.7rem;
}

.analyst-synthesis-detail-group ul {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.25rem 1rem;
  margin: 0.25rem 0 0 !important;
  padding-left: 1rem;
  color: var(--text-muted);
  font-size: 0.7rem;
}

@media (max-width: 520px) {
  .analyst-synthesis-card { padding: 0.85rem; }
  .analyst-synthesis-card-header { align-items: flex-start; }
  .analyst-category { flex-basis: 115px; }
}


.ui-section-heading::after {
  content: '';
  align-self: flex-end;
  width: 2.25rem;
  height: 2px;
  margin-left: auto;
  margin-bottom: -0.71rem;
  border-radius: 999px;
  background: var(--brand-gradient);
  box-shadow: 0 0 12px rgba(0, 210, 255, 0.22);
}

.ui-section-heading svg {
  flex-shrink: 0;
  margin-right: 0 !important;
  opacity: 0.9;
}

/* Compact context row below the primary asset selector. */
.selection-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  margin: -0.15rem 0 0.9rem;
  padding: 0.65rem 0.8rem;
  border: 1px solid rgba(71, 91, 118, 0.52);
  border-radius: var(--radius-sm);
  background: rgba(14, 21, 36, 0.58);
  color: var(--text-muted);
  font-size: 0.76rem;
  line-height: 1.35;
}

.selection-summary-main {
  display: inline-flex;
  align-items: baseline;
  gap: 0.4rem;
  min-width: 0;
}

.selection-summary-count {
  color: var(--text-main);
  font-family: var(--font-mono);
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
}

.selection-summary-context {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.selection-summary-source {
  flex-shrink: 0;
  color: var(--brand-secondary);
  font-family: var(--font-mono);
  font-size: 0.67rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.selection-summary-source i {
  color: var(--text-faint);
  font-style: normal;
}

/* Onboarding surface shown before the first analysis. */
.onboarding-card {
  position: relative;
  overflow: hidden;
  margin: 1.5rem 0 0.4rem;
  padding: 1.35rem;
  border: 1px solid rgba(71, 91, 118, 0.72);
  border-radius: var(--radius-lg);
  background:
    radial-gradient(circle at 100% 0%, rgba(0, 210, 255, 0.1), transparent 32%),
    linear-gradient(135deg, rgba(14, 27, 47, 0.92), rgba(8, 12, 20, 0.94));
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

.onboarding-card::before {
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  content: '';
  background: var(--brand-gradient);
}

.onboarding-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.15rem;
}

.onboarding-eyebrow {
  margin-bottom: 0.35rem;
  color: var(--brand-primary);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.onboarding-title {
  color: var(--text-main);
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.015em;
}

.onboarding-description {
  max-width: 680px;
  margin: 0.4rem 0 0;
  color: var(--text-muted);
  font-size: 0.82rem;
  line-height: 1.55;
}

.onboarding-signal {
  display: inline-flex;
  align-items: flex-end;
  gap: 0.22rem;
  padding: 0.35rem 0.55rem;
  border: 1px solid rgba(0, 255, 135, 0.16);
  border-radius: 999px;
  background: rgba(0, 255, 135, 0.045);
}

.onboarding-signal span {
  display: block;
  width: 0.27rem;
  height: 0.45rem;
  border-radius: 999px;
  background: var(--brand-primary);
  opacity: 0.75;
}

.onboarding-signal span:nth-child(2) {
  height: 0.72rem;
  background: var(--brand-secondary);
}

.onboarding-signal span:nth-child(3) {
  height: 1rem;
  background: var(--brand-accent);
}

.onboarding-tip-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.7rem;
}

.onboarding-tip {
  min-height: 7rem;
  padding: 0.85rem;
  border: 1px solid rgba(71, 91, 118, 0.54);
  border-top: 2px solid var(--tip-color);
  border-radius: var(--radius-md);
  background: rgba(8, 12, 20, 0.42);
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
}

.onboarding-tip:hover {
  transform: translateY(-2px);
  border-color: var(--tip-color);
  background: rgba(19, 29, 46, 0.76);
}

.onboarding-tip-green { --tip-color: var(--brand-primary); }
.onboarding-tip-blue { --tip-color: var(--brand-secondary); }
.onboarding-tip-purple { --tip-color: #a855f7; }

.onboarding-tip-label {
  display: flex;
  align-items: center;
  gap: 0.38rem;
  margin-bottom: 0.55rem;
  color: var(--tip-color);
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.onboarding-tip-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.15rem;
  height: 1.15rem;
  border: 1px solid var(--tip-color);
  border-radius: 50%;
  background: rgba(8, 12, 20, 0.45);
  color: var(--tip-color);
  font-family: var(--font-mono);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0;
}

.onboarding-tip-copy {
  color: #cbd5e1;
  font-size: 0.78rem;
  line-height: 1.5;
}

.onboarding-tip-purple .onboarding-tip-copy b {
  color: #c084fc;
}

.onboarding-subheading {
  margin: 1.35rem 0 0.55rem;
  color: var(--text-main);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.onboarding-subheading span {
  color: var(--text-faint);
  font-weight: 500;
}

.onboarding-subheading-spaced {
  margin-top: 1.55rem;
}

.quick-start-sector {
  margin: 0.05rem 0 0.3rem;
  color: var(--quick-color);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-align: center;
  text-transform: uppercase;
}

.onboarding-hint {
  display: flex;
  align-items: flex-start;
  gap: 0.45rem;
  margin-top: 1.2rem;
  padding: 0.75rem 0.9rem;
  border-left: 2px solid rgba(56, 189, 248, 0.55);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  background: rgba(0, 0, 0, 0.2);
  color: var(--text-muted);
  font-size: 0.76rem;
  line-height: 1.5;
}

.onboarding-hint svg {
  flex-shrink: 0;
  margin-top: 0.08rem;
}

.onboarding-hint b {
  flex-shrink: 0;
  color: var(--text-main);
}

/* Sidebar navigation should read as a workspace switcher, not a raw menu. */
[data-testid="stSidebar"] {
  background:
    linear-gradient(180deg, rgba(14, 21, 36, 0.98), rgba(8, 12, 20, 0.98)) !important;
}

[data-testid="stSidebarNavLink"] {
  min-height: 2.45rem;
  display: flex;
  align-items: center;
}

[data-testid="stSidebarNavLink"][aria-current="page"] {
  box-shadow: inset 0 0 18px rgba(0, 255, 135, 0.04), 0 6px 16px rgba(0, 0, 0, 0.14);
}

@media (max-width: 768px) {
  .selection-summary {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.35rem;
  }

  .selection-summary-context {
    white-space: normal;
  }

  .selection-summary-source {
    font-size: 0.62rem;
  }

  .onboarding-card {
    padding: 1.1rem;
  }

  .onboarding-tip-grid {
    grid-template-columns: 1fr;
  }

  .onboarding-tip {
    min-height: 0;
  }
}

@media (max-width: 480px) {
  .onboarding-card-header {
    display: block;
  }

  .onboarding-signal {
    margin-top: 0.8rem;
  }
}
/* ─── Quiet editorial pass ──────────────────────────────────────────────────
   The product is a financial workspace, not a marketing landing page. Keep
   hierarchy, interaction and data semantics; remove decorative noise. */
:root {
  --brand-primary: #61d4c6;
  --brand-secondary: #8cb4f2;
  --brand-accent: #e7b96b;
  --brand-danger: #e58a93;
  --brand-info: #b7a2e6;
  --brand-gradient: var(--brand-primary);
  --bg-color: #0b111a;
  --panel-bg: #151d2a;
  --panel-raised: #1d2938;
  --panel-border: #34465b;
  --primary-color: #61d4c6;
  --secondary-color: #8cb4f2;
  --accent-color: #e7b96b;
  --border-color: #34465b;
  --border-glow: transparent;
  --text-main: #f0f4f8;
  --text-muted: #aebaca;
  --text-faint: #748297;
  --font-display: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: "SFMono-Regular", "Cascadia Code", "Roboto Mono", monospace;
  --radius-lg: 10px;
  --radius-md: 8px;
  --radius-sm: 5px;
  --border-radius-lg: 10px;
  --border-radius-md: 8px;
  --border-radius-sm: 5px;
  --shadow-glow: none;
  --shadow-glow-strong: none;
  --shadow-dark: none;
  --surface-glass: #151d2a;
  --surface-hover: #202d3c;
  --focus-ring: 0 0 0 3px rgba(97, 212, 198, 0.25);
}

.stApp,
[data-testid="stAppViewContainer"] {
  background: var(--bg-color) !important;
  color: var(--text-main) !important;
}

body,
.stApp,
[data-testid="stSidebar"],
button,
input,
textarea,
[data-baseweb="select"] {
  font-family: var(--font-display) !important;
}

h1:not(.page-hero-title),
h2,
h3,
h4,
h5,
h6 {
  background: none !important;
  -webkit-background-clip: initial !important;
  background-clip: initial !important;
  -webkit-text-fill-color: var(--text-main) !important;
  color: var(--text-main) !important;
}

/* Navigation is a workspace rail, not a glowing progress panel. */
[data-testid="stSidebar"] {
  background: #0f1519 !important;
  border-right: 1px solid #202c33 !important;
  box-shadow: none !important;
}

[data-testid="stSidebarNavLink"] {
  min-height: 2.2rem !important;
  margin: 2px 0.55rem !important;
  border-left: 2px solid transparent !important;
  border-radius: 5px !important;
}

[data-testid="stSidebarNavLink"] span {
  color: #aab5b8 !important;
  font-size: 0.84rem !important;
  font-weight: 500 !important;
}

[data-testid="stSidebarNavLink"]:hover {
  background: #172126 !important;
}

[data-testid="stSidebarNavLink"][aria-current="page"] {
  background: #18251f !important;
  border-left-color: var(--brand-primary) !important;
  box-shadow: none !important;
}

[data-testid="stSidebarNavLink"][aria-current="page"] span {
  color: var(--brand-primary) !important;
  font-weight: 650 !important;
}

.sidebar-section-label {
  border-bottom-color: #253239 !important;
  color: #91a0a4 !important;
  letter-spacing: 0.08em !important;
}

/* Keep each page header useful as orientation, without hero-card theatre. */
.page-hero {
  min-height: 0 !important;
  gap: 1rem !important;
  padding: 1.1rem 1.2rem !important;
  background: #11181d !important;
  border: 1px solid #293840 !important;
  border-left: 3px solid #719b80 !important;
  border-radius: 8px !important;
  box-shadow: none !important;
  transition: border-color 160ms ease !important;
}

.page-hero::after,
.page-hero:hover::after {
  display: none !important;
}

.page-hero:hover,
.main-hero:hover {
  border-left-color: #9ad7b1 !important;
  box-shadow: none !important;
}

.page-hero-icon,
.main-hero .page-hero-icon {
  width: 42px !important;
  height: 42px !important;
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  filter: grayscale(1) saturate(0.2) opacity(0.7) !important;
  box-shadow: none !important;
}

.page-hero-icon svg {
  max-width: 38px;
  max-height: 38px;
}

.page-hero-title,
.page-hero-title[style] {
  background: none !important;
  -webkit-background-clip: initial !important;
  background-clip: initial !important;
  -webkit-text-fill-color: var(--text-main) !important;
  color: var(--text-main) !important;
  font-size: clamp(1.35rem, 2.2vw, 1.85rem) !important;
  letter-spacing: -0.025em !important;
}

.page-hero-subtitle {
  max-width: 760px !important;
  color: #9ca9ae !important;
  font-size: 0.9rem !important;
  line-height: 1.5 !important;
}

/* Flat controls with a clear primary action. */
.stButton > button,
.stDownloadButton > button,
.stFormSubmitButton > button,
[data-testid="stFormSubmitButton"] > button {
  min-height: 2.4rem !important;
  padding: 0.55rem 1rem !important;
  background: #141d22 !important;
  border: 1px solid #304049 !important;
  border-radius: 7px !important;
  color: #dce7df !important;
  box-shadow: none !important;
  font-weight: 600 !important;
  letter-spacing: 0 !important;
  transition: background 160ms ease, border-color 160ms ease, color 160ms ease !important;
}

.stButton > button:hover,
.stDownloadButton > button:hover,
.stFormSubmitButton > button:hover,
[data-testid="stFormSubmitButton"] > button:hover {
  transform: none !important;
  background: #1a2620 !important;
  border-color: #7eb492 !important;
  color: #dff2e5 !important;
  box-shadow: none !important;
}

[data-testid="baseButton-primary"],
[data-testid="stFormSubmitButton"] > button {
  background: #a6d9b6 !important;
  border-color: #a6d9b6 !important;
  color: #0b1410 !important;
}

[data-testid="baseButton-primary"]:hover,
[data-testid="stFormSubmitButton"] > button:hover {
  background: #bee7c9 !important;
  border-color: #bee7c9 !important;
  color: #0b1410 !important;
}

.stTextInput input,
.stNumberInput input,
.stDateInput input,
.stSelectbox div[data-baseweb="select"] > div,
.stMultiSelect div[data-baseweb="select"] > div {
  background: #0e1519 !important;
  border-color: #2c3b43 !important;
  border-radius: 7px !important;
  color: var(--text-main) !important;
  font-family: var(--font-display) !important;
}

.stTextInput input:focus,
.stNumberInput input:focus,
.stDateInput input:focus,
.stSelectbox div[data-baseweb="select"]:focus-within > div,
.stMultiSelect div[data-baseweb="select"]:focus-within > div {
  border-color: #7eb492 !important;
  box-shadow: var(--focus-ring) !important;
}

[data-baseweb="popover"] [data-baseweb="menu"] {
  background: #11181d !important;
  border-color: #2c3b43 !important;
  box-shadow: 0 16px 28px rgba(0, 0, 0, 0.28) !important;
}

[data-baseweb="popover"] [role="option"] {
  color: #aab5b8 !important;
  font-family: var(--font-display) !important;
}

[data-baseweb="popover"] [role="option"]:hover,
[data-baseweb="popover"] [role="option"][aria-selected="true"] {
  background: #18251f !important;
  color: var(--brand-primary) !important;
}

/* Section titles are rules for scanning, not decorative gradient bars. */
.ui-section-heading {
  margin: 1.35rem 0 0.65rem !important;
  padding: 0 0 0.55rem !important;
  border-bottom-color: #293840 !important;
  font-size: 1.02rem !important;
  letter-spacing: -0.01em !important;
}

.ui-section-heading::after {
  width: 1.5rem !important;
  height: 1px !important;
  margin-bottom: -0.61rem !important;
  border-radius: 0 !important;
  background: #91c9a4 !important;
  box-shadow: none !important;
}

.ui-section-heading svg {
  filter: grayscale(1) saturate(0.25) !important;
  opacity: 0.72 !important;
}

.selection-summary {

